{"test_code":"from textutil.trunc import truncate


def test_truncate_result_not_longer_than_max_len() -> None:
    result = truncate('hello world', 5)
    assert len(result) <= 5


def test_truncate_result_fits_with_custom_ellipsis() -> None:
    result = truncate('hello world', 8, '..')
    assert len(result) <= 8
","rationale":"Checks that truncating 'hello world' to 5 characters (and to 8 with a custom ellipsis) yields a string no longer than max_len, which currently fails because the ellipsis is appended after slicing to max_len."}
